}

function slugify(value) {
  return cleanString(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function pickFrom(source, keys) {
  if (!source || typeof source !== 'object') return '';
  for (const key of keys) {
    if (!(key in source)) continue;
    const value = source[key];
    if (Array.isArray(value)) {
      const cleaned = value.map((v) => cleanString(v)).filter(Boolean);
      if (cleaned.length) return cleaned;
      continue;
    }
    const cleaned = cleanString(value);
    if (cleaned) return cleaned;
  }
  return '';
}

function pick(keys) {
  const fromAnswers = pickFrom(answers, keys);
  if (Array.isArray(fromAnswers)) return fromAnswers;
  if (fromAnswers) return fromAnswers;
  const fromRoot = pickFrom(root, keys);
  if (Array.isArray(fromRoot)) return fromRoot;
  if (fromRoot) return fromRoot;
  return '';
}

function pickList(keys) {
  const value = pick(keys);
  if (Array.isArray(value)) {
